// ---- the registers each lesson carries (who-he-is.js registerFor) -------------
export const WHO_HE_IS_LESSON_SPECS = Object.freeze({
  'whohe1-all-of-them-the-rule-the-line-and-the-edge': { sits: [], points: [], edge: true },
  'whohe2-before-time-and-the-beginning': { sits: ['before-time', 'creation'], points: ['before-time', 'creation'] },
  'whohe3-the-fathers-and-moses': { sits: ['patriarchs', 'moses', 'the-land'], points: [] },
  'whohe4-the-kings-and-the-psalms': { sits: ['kings'], points: [] },
  'whohe5-the-prophets': { sits: ['prophets'], points: [] },
  'whohe6-he-comes-in-the-flesh': { sits: ['incarnation'], points: ['incarnation'] },
  'whohe7-his-ministry-every-scene': { sits: ['ministry'], points: [] },
  'whohe8-the-cross': { sits: ['cross'], points: ['cross'] },
  'whohe9-he-is-risen-and-he-goes-up': { sits: ['resurrection', 'ascension'], points: ['resurrection', 'ascension'] },
  'whohe10-his-witnesses-in-acts': { sits: ['church'], books: ['Acts'], points: [] },
  'whohe11-the-letters-who-he-is-to-the-churches': { sits: ['church'], books: [...LETTER_BOOKS], points: [] },
  'whohe12-the-revelation-of-jesus-christ': { sits: ['church'], books: ['Revelation'], points: [] },
  'whohe13-he-comes-again': { sits: [], points: ['the-end'] },
  'whohe14-for-ever': { sits: [], points: ['forever'] },
});
const R = Object.fromEntries(Object.entries(WHO_HE_IS_LESSON_SPECS).map(([id, s]) => [id, registerFor(s)]));
const P = (id) => R[id].primary.length;
const ERAS_N = WHO_HE_IS_ERAS.length;
const booksIn = (id) => new Set(R[id].primary.map((e) => e.book)).size;
const preIn = (id) => R[id].primary.filter((e) => e.present === 'pre-incarnate').length;
const Q = (id) => R[id].pointing.length;

/** The lesson whose register holds an entry as one of its own (for the timeline). */
export function whoHeIsLessonFor(entry) {
  for (const [id, r] of Object.entries(R)) if (r.primary.some((e) => e.id === entry.id)) return id;
  return null;
}

const ID = Object.keys(WHO_HE_IS_LESSON_SPECS);

